def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = op.count('C')
    op_d = n - op_c
    last_me = my[-1]
    last_op = op[-1]

    # Compute mutual cooperation count and total scores
    mutual_c = 0
    my_score = 0
    op_score = 0
    for i in range(n):
        a, b = history[i]
        if a == 'C' and b == 'C':
            mutual_c += 1
            my_score += 3
            op_score += 3
        elif a == 'C' and b == 'D':
            op_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            op_score += 1

    # Count consecutive opponent defections at the end
    streak_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            streak_d += 1
        else:
            break

    # Count consecutive opponent cooperations at the end
    streak_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            streak_c += 1
        else:
            break

    # Near end: exploit cooperators, defend against defectors
    remaining = 100 - n
    if remaining <= 1:
        if op_c >= op_d and op_c >= 1:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    if remaining <= 4:
        if op_c * 2 >= n and op_d <= (n // 3):
            return 'D'
        if last_op == 'D' and streak_d >= 2:
            return 'D'
        if last_op == 'C':
            return 'D' if op_d < n * 0.4 else 'C'
        return 'D' if op_d * 2 > n else 'C'

    # Detect always-defect
    if n >= 6 and op_c == 0:
        return 'D'

    # Detect extremely cooperative opponents: keep cooperating early, exploit late
    if n >= 8 and op_d == 0:
        return 'C'

    # Detect opponent who defected first round and never cooperated since
    if n >= 5 and op_c == 0:
        return 'D'

    # Opponent mostly cooperative: preserve mutual cooperation with rare probing
    if op_d * 5 <= n:
        # Strong cooperative partner
        if mutual_c >= n - 2:
            # Almost perfect mutual cooperation - keep it
            return 'C'
        if n >= 20 and n % 19 == 0 and remaining > 10:
            return 'D'
        return 'C'

    # Opponent heavily defecting: defect, but probe occasionally for recovery
    if op_d * 2 >= n:
        if streak_d >= 2:
            # Try to break mutual defection occasionally when partnership might recover
            if streak_c == 0 and streak_d >= 3 and n > 15:
                if rng.random() < 0.12:
                    return 'C'
            return 'D'
        # Single-ish defection in a mostly-defect context
        return 'D'

    # Mixed opponent: tit-for-tat with forgiveness

    # If both cooperated last round, stay cooperative with occasional probe
    if last_me == 'C' and last_op == 'C':
        if streak_c >= 3 and my_score < op_score - 5 and remaining > 5:
            # Trailing and mutual cooperation - try a probe
            if rng.random() < 0.15:
                return 'D'
        return 'C'

    # Opponent just defected
    if last_op == 'D':
        if streak_d >= 3:
            # Long mutual defection likely; try to restore cooperation once more
            if streak_d == 3 and my_score >= op_score - 3:
                if rng.random() < 0.25:
                    return 'C'
            return 'D'
        if streak_d == 2:
            # Punish two rounds, then likely forgive
            return 'D'
        # Single defection - retaliate once, then forgive next opportunity
        if last_me == 'D':
            # We already retaliated; return to cooperation to break the cycle
            return 'C'
        return 'D'

    # Opponent just cooperated
    if last_op == 'C':
        if last_me == 'D':
            # They forgave our defection; resume cooperation
            return 'C'
        # Both cooperating previously; maintain
        if last_me == 'C':
            return 'C'

    return 'C'
